const staticData = $getWorkflowStaticData('global');
const body = $input.first().json.body ?? $input.first().json;

// Normalize station ID — lowercase, spaces to underscores
const stationId = String(body.station_id ?? body.id ?? 'unknown')
  .toLowerCase()
  .replace(/\s+/g, '_');
const stationName = body.station_name ?? body.name ?? stationId;

if (!staticData.stations) {
  staticData.stations = {};
}

// Stamp last_seen; preserve last_alerted if it exists
staticData.stations[stationId] = {
  ...( staticData.stations[stationId] || {} ),
  id: stationId,
  name: stationName,
  last_seen: new Date().toISOString()
};

return [{
  json: {
    success: true,
    station_id: stationId,
    station_name: stationName,
    recorded_at: staticData.stations[stationId].last_seen
  }
}];

const staticData = $getWorkflowStaticData('global');
const now = new Date();
const THRESHOLD_MS = 30 * 60 * 1000;  // alert after 30 min silence
const COOLDOWN_MS  = 30 * 60 * 1000;  // re-alert at most once per 30 min

if (!staticData.stations || Object.keys(staticData.stations).length === 0) {
  return [{ json: { overdueStations: [] } }];
}

const overdueStations = [];

for (const [id, station] of Object.entries(staticData.stations)) {
  const lastSeen  = new Date(station.last_seen);
  const elapsed   = now - lastSeen;
  const minutesAgo = Math.floor(elapsed / 60000);

  if (elapsed > THRESHOLD_MS) {
    const lastAlerted  = station.last_alerted ? new Date(station.last_alerted) : null;
    const shouldAlert  = !lastAlerted || (now - lastAlerted >= COOLDOWN_MS);

    if (shouldAlert) {
      overdueStations.push({
        id,
        name: station.name,
        last_seen: station.last_seen,
        minutes_ago: minutesAgo
      });
      staticData.stations[id].last_alerted = now.toISOString();
    }
  }
}

return [{ json: { overdueStations, check_time: now.toISOString() } }];

const stations = $input.first().json.overdueStations;

const lines = stations.map(s => {
  const h = Math.floor(s.minutes_ago / 60);
  const m = s.minutes_ago % 60;
  const timeStr = h > 0 ? `${h}h ${m}m` : `${m}m`;
  const lastSeenStr = new Date(s.last_seen).toLocaleString('en-US', {
    timeZone: 'America/New_York',
    month: 'short',
    day: 'numeric',
    hour: 'numeric',
    minute: '2-digit'
  });
  return `:warning: *${s.name}* — last seen ${timeStr} ago (${lastSeenStr} ET)`;
});

const count = stations.length;
const message = `:satellite: *Weather Station Alert*\n${
  count === 1 ? 'A station has' : `${count} stations have`
} not reported in over 30 minutes:\n\n${lines.join('\n')}`;

return [{ json: { message } }];
